/**
 * Every photo the site shows that is not tied to a single product lives here,
 * so real photos can be swapped in without touching components.
 *
 * Local product photos are generated by `npm run images` and come in two
 * widths; SmartImage builds the srcset from the "-960.webp" path. Remote URLs
 * (Unsplash, Supabase Storage…) work too and are used as they are.
 */
export const productImage = (slug, n = 1) => `/images/products/${slug}-${n}-960.webp`

